import 'package:flutter/material.dart';

void main() {
  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      home: WinxGridPage(),
    );
  }
}

class WinxGridPage extends StatelessWidget {

    final List<Map<String, String>> fadinhas = [
    
    {
      'nome': 'Stella',
      'url': 'data:image/jpeg;base64,'
    },
    {
      'nome': 'Bloom',
      'url': 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQo6yKhq0Xzf0mo66jvgNju-b97p2dA4S07Qw&s'
    },
    {
      'nome': 'Flora',
      'url': 'data:image/jpeg;base64,'
    },
    {
      'nome': 'Musa',
      'url': 'data:image/jpeg;base64,'
    },
    {
      'nome': 'Tecna',
      'url': 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRTEKAeg_rF72pMLvVu9bFREsELv-DGMmZT0Q&s'
    },
    {
      'nome': 'Layla',
      'url': 'data:image/jpeg;base64,'
    },
  ];

  WinxGridPage({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Winx Club Grid'),
        backgroundColor: Colors.pinkAccent,
      ),
      body: Padding(
        padding: const EdgeInsets.all(8.0),
        // Implementação do GridView
        child: GridView.builder(
          gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
            crossAxisCount: 2, // 2 colunas como na imagem
            crossAxisSpacing: 10, // Espaço horizontal
            mainAxisSpacing: 10,    // Espaço vertical
          ),
          itemCount: fadinhas.length,
          itemBuilder: (context, index) {
            return ClipRRect(
              borderRadius: BorderRadius.circular(8), 
              child: GridTile(
                footer: Container(
                  padding: const EdgeInsets.all(8),
                  color: Colors.black45, 
                  child: Text(
                    fadinhas[index]['nome']!,
                    style: const TextStyle(
                      color: Colors.white,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ),
                child: Image.network(
                  fadinhas[index]['url']!,
                  fit: BoxFit.cover, 
                  errorBuilder: (context, error, stackTrace) {
                    return Container(
                      color: Colors.pink[100],
                      child: const Icon(Icons.auto_fix_high, color: Colors.pink),
                    );
                  },
                ),
              ),
            );
          },
        ),
      ),
    );
  }
}